#!/bin/sh
# Apply Project OGRE's patches to the reccmp installed in toolchain/venv (pinned a0f494c0, see
# tools/requirements.txt). Idempotent: an already-applied patch is skipped. Re-run after every
# "pip install -r tools/requirements.txt".
#
#   sh tools/reccmp-patches/apply.sh
#
# 0001-ogre-imports-and-vc9-funcinfo.patch
#   - CSV type "import": an IAT slot named "DLL::function". PLAYER's import directory is VMProtect's
#     table in .vmp1, but .text calls through the linker's IAT at 0x00aa1000 in .rdata;
#     reccmp/player-imports.csv names those slots (generated by tools/ida/gen_reccmp_csv.py).
#   - match_imports keeps the lowest address per name, so a recomp import pairs with that slot and
#     not with VMProtect's copy.
#   - import thunks (jmp [slot]) are also found for CSV-supplied import slots.
#   - FuncInfo magic 0x19930521/0x19930522 accepted (upstream only searches 0x19930520, so a VC9
#     image yields almost no __ehfuncinfo/__Unwind labels).
set -e
cd "$(dirname "$0")/../.."
SP=$(toolchain/venv/bin/python -c 'import sysconfig; print(sysconfig.get_paths()["purelib"])')
for p in tools/reccmp-patches/*.patch; do
    if patch -p1 -R --dry-run -s -f -d "$SP" < "$p" > /dev/null 2>&1; then
        echo "already applied: $p"
    else
        patch -p1 -N -d "$SP" < "$p"
    fi
done
